// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IRegistry {
    function isManufacturer(address _user) external view returns (bool);
}

contract Products {
    struct Product {
        string name;
        address manufacturer;
        bool isActive;
        string description;
        string sideEffect;
    }

    struct Batch {
        bytes32 productId;
        string ipfsUrl;
    }

    mapping(bytes32 => Product) public products;
    mapping(bytes32 => Batch[]) public productBatches;

    IRegistry public registry;

    event ProductRegistered(bytes32 indexed productId, string name, address manufacturer);
    event BatchAdded(bytes32 indexed productId, string ipfsUrl);

    constructor(address _registryAddress) {
        registry = IRegistry(_registryAddress);
    }

    modifier onlyManufacturer() {
        require(registry.isManufacturer(msg.sender), "Not a registered manufacturer");
        _;
    }

    function registerProduct(
        string memory _name,
        string memory _description,
        string memory _sideEffect,
        uint256 _nonce
    ) public onlyManufacturer returns (bytes32) {
        bytes32 productId = keccak256(
            abi.encodePacked(msg.sender, _name, _description, _sideEffect, _nonce, block.timestamp)
        );

        require(products[productId].manufacturer == address(0), "Product already exists");

        products[productId] = Product({
            name: _name,
            manufacturer: msg.sender,
            isActive: true,
            description: _description,
            sideEffect: _sideEffect
        });

        emit ProductRegistered(productId, _name, msg.sender);
        return productId;
    }

    function addBatch(bytes32 _productId, string memory _ipfsUrl) public onlyManufacturer {
        require(products[_productId].manufacturer == msg.sender, "Not manufacturer");
        require(products[_productId].isActive, "Product inactive");

        productBatches[_productId].push(Batch({
            productId: _productId,
            ipfsUrl: _ipfsUrl
        }));

        emit BatchAdded(_productId, _ipfsUrl);
    }

    function getProduct(bytes32 _productId) public view returns (Product memory) {
        return products[_productId];
    }

    function getBatches(bytes32 _productId) public view returns (Batch[] memory) {
        return productBatches[_productId];
    }
}
